import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse(`{"title":"Page 34 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"34","title":"Page 34 | Home","prev":"/page/33/","next":"/page/35/","posts":[{"title":"Archlinux下声卡的设置与折腾","url":"/posts/2014-06-05-archlinux-sound-setting/","date":"2014-06-05 09:22","tags":["linux"],"html":"<p>最近又有瞎折腾装 Arch....发现显卡驱动的安装和设置都不是问题...\\n声卡却老是出现奇怪的问题,便把最近折腾的经验写下来吧~</p>\\n<h2 id=\\"切换默认声卡\\" tabindex=\\"-1\\">切换默认声卡 <a class=\\"header-anchor\\" href=\\"#切换默认声卡\\" aria-label=\\"Permalink to &quot;切换默认声卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现最近的新本子基本上声卡设备都不止一个,个人猜测应该是 HDMI 音频输出和\\n本机主板上的音频输出吧.可以使用 <code>aplay -l</code> 命令显示所有声卡设备.\\n我机器的输出是:</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">[acgotaku@Archlinux </span><span style=\\"color:#D73A49\\">~</span><span style=\\"color:#24292E\\">]$ aplay -l</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">****</span><span style=\\"color:#24292E\\"> List of PLAYBACK Hardware Devices </span><span style=\\"color:#D73A49\\">****</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> HDMI],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 3:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\"> [HDMI </span><span style=\\"color:#032F62\\">0]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 1:</span><span style=\\"color:#032F62\\"> PCH</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> PCH],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> ALC3220</span><span style=\\"color:#032F62\\"> Analog</span><span style=\\"color:#24292E\\"> [ALC3220 </span><span style=\\"color:#032F62\\">Analog]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>第一个一般为默认的声卡输出设备,显然 HDMI 输出是不对的,导致声音无法正常播放,我们应该把默认声卡切换为\\n第二个.最简单易用的方法是在用户根目录下新建一个 .asoundrc 文件.输入以下内容:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>defaults.pcm.card 1</span></span>\\n<span class=\\"line\\"><span>defaults.pcm.device 0</span></span>\\n<span class=\\"line\\"><span>defaults.ctl.card 1</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>上面的数据可以从声卡设备输出中找到,这样就切换到 card 1 的 device 0 设备了.不过切换之后可能发现还是没有\\n声音,因为 alsa 默认是静音的需要手动解除才行. 这就需要去官方源安装 <code>alsamixer</code> 工具. <a href=\\"https://www.archlinux.org/packages/?name=alsa-utils\\" target=\\"_blank\\" rel=\\"noreferrer\\">alsa-utils</a>\\n我自己安装的 alsamixer 使用界面是:</p>\\n<p><img src=\\"/assets/alsamixer.png\\" alt=\\"alsamixer\\"></p>\\n<p>默认 Master 竖条下方显示的不是 00 而是 MM,表示是静音的,按下 m 键解除静音.</p>\\n<h2 id=\\"耳机有持续的杂音的解决方案\\" tabindex=\\"-1\\">耳机有持续的杂音的解决方案 <a class=\\"header-anchor\\" href=\\"#耳机有持续的杂音的解决方案\\" aria-label=\\"Permalink to &quot;耳机有持续的杂音的解决方案&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些情况下即使安装好 alsa 解除静音了,但仍然发现戴耳机的时候没有任何软件发声的时候会有持续的杂音,但是音乐播放器一旦放音乐的时候杂音又消失了.\\n这个问题的原因是 alsa 默认设置 Mic 声道是静音的,我们只需要解除 Mic 声道的静音并调节至合适的值即可.</p>\\n<h2 id=\\"恢复默认的-alsa-设置\\" tabindex=\\"-1\\">恢复默认的 alsa 设置 <a class=\\"header-anchor\\" href=\\"#恢复默认的-alsa-设置\\" aria-label=\\"Permalink to &quot;恢复默认的 alsa 设置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些时候自己胡乱设置导致 alsa 无法正常工作的时候可以通过使用 <code>alsactl restore</code> 命令使 alsa 恢复到默认的配置一般都能正常工作了.</p>\\n"},{"title":"JavaScript中一个经典的正则例子","url":"/posts/2014-05-08-javascript-regular-expressions/","date":"2014-05-08 09:44","tags":["js","regex"],"html":"<p>学习知识的最好方法就是看例子.(个人观点) 因为书上总是会把概念和公式讲的晦涩难懂,才显得作者高大上.所以我总是喜欢\\n通过例子学习知识.每次写正则的时候总是喜欢查看例子学习如何使用,因为正则实在太耗脑细胞了,记不住,也没必要记住.学会\\n如何使用并在项目中熟练运用就好了,经常使用的话也就自然记住了.</p>\\n<p>JavaScript 语言精粹上面有个非常棒的学习例子,每次写正则的时候都会想起它.所以还是记一下分享给大家也方面我查询啦~</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> parse_url </span><span style=\\"color:#D73A49\\">=</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  /</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#032F62\\">(?:(</span><span style=\\"color:#005CC5\\">[A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">):)</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#D73A49\\">{0,3}</span><span style=\\"color:#032F62\\">)(</span><span style=\\"color:#005CC5\\">[0-9.\\\\-A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">)(?::(</span><span style=\\"color:#005CC5\\">\\\\d</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">?#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:#(</span><span style=\\"color:#005CC5\\">.</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?$</span><span style=\\"color:#032F62\\">/</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> url </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://www.ora.com:80/goodparts?q#fragment'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> result </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> parse_url.</span><span style=\\"color:#6F42C1\\">exec</span><span style=\\"color:#24292E\\">(url);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> names </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#032F62\\">'url'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'scheme'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'slash'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'host'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'port'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'path'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'query'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hash'</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> blanks </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> '     '</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> names.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">+=</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(names[i] </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> ':'</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> blanks.</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(names[i].</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">), result[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>让我们分解 parse_url 的各个部分,看看它是如何工作的:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>^</code>字符表示此字符串的开始.它是一个锚,指引 exec 不要跳过那些不像 URL(non-URL-like)的前缀,只匹配那些从开头就像 URL 一样的字符串:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:([A-Za-z]+):)?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个因子匹配一个协议名,但仅当它后面跟随一个:(冒号)的时候才匹配.(?:...)表示一个非捕获型分组(noncapturing group).\\n后缀 ? 表示这个分组是可选的. 问号表示重复 0 次或一次.(...)表示一个捕获型分组(capturing group).一个捕获型分组会复制它\\n所匹配的文本,并把其放到 result 数组里.每个捕获型分组都会被指定一个编号.第一个捕获型分组的编号是 1,所以该分组所匹配的文本副本\\n会出现在 result[1]中.[...]表示一个字符类,A-Za-z 这个字符类包含 26 个大写字母和 26 个小写字母.连字符( - )表示范围从 A 到 Z.\\n后缀 + 表示这个字符类会被匹配一次或者多次.这个组后面跟着字符:,它会按字面进行匹配:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(\\\\/{0,3})</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 2./表示该匹配/(斜扛).它是\\\\(反斜杠)来进行转义,这样它就不会被错误地解释为这个正则表达式的结束符.后缀{0,3}表示\\n/ 会被匹配 0 次,或者 1~3 次:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>([0-9.\\\\-A-Za-z]+)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 3.它会匹配一个主机名,由一个或多个数字、字母,以及 . 或 - 字符组成. - 会被转义为 \\\\- 以防止与表示范围的连字符想混淆:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?::(\\\\d+))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个可选的因子匹配端口号,它是由一个前置 : 加上一个或多个数字而组成的序列. \\\\d 表示一个数字字符.一个或多个数字组成的数字串会被捕获型\\n分组 4 捕获:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\/([^?#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来是另一个可选的分组.该分组以一个 / 开始. 之后的字符类[^?#]以一个 ^ 开始, 它表示这个类包含除了?和#之外的所有字符.*表示这个字符类\\n会被匹配 0 次或多次.</p>\\n<p>注意这里的处理是不严谨的.这个类匹配除?和#之外的所有字符,其中包括了行结束符、控制字符,以及其他大量不应在此被匹配的字符.大多数情况下,它会按照\\n我们的预期去做,但某些恶意文本可能会有渗透进来的风险.不严谨的正则表达式是一个常见的安全漏洞发源地.写不严谨的正则表达式比写严谨的正则表达式要容易得多.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\?([^#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来,还有一个以一个 ? 开始的可选分组.它包含捕获型分组 6,这个分组包含 0 个或多个非#字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:#(.*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最后一个可选分组是以 # 开始的 .会匹配除行结束符以外的所有字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>$表示这个字符串的结束.它保证在这个 URL 的尾部没有其他更多内容了.</p>\\n"},{"title":"JavaScript函数中的闭包","url":"/posts/2014-04-30-javascript-closure/","date":"2014-04-30 16:18","tags":["js","closure"],"html":"<p>JavaScript 中的闭包通常被视作 JavaScript 的高级特性.但是我看了好几次文档也没有明白过来.也没有实际应用过.最近重新学习 JavaScript\\n打算好好学习下.</p>\\n<h2 id=\\"什么是闭包\\" tabindex=\\"-1\\">什么是闭包 <a class=\\"header-anchor\\" href=\\"#什么是闭包\\" aria-label=\\"Permalink to &quot;什么是闭包&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>闭包用通俗的说法来理解就是子函数可以使用父函数中的局部变量,这种行为叫做闭包.这个变量不是在这个代码块内或者全局上下文中定义的,而是\\n在定义代码块的环境中定义的(局部变量).一个经典的例子就是:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> a</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  function</span><span style=\\"color:#6F42C1\\"> b</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    alert</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">i);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> b;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> c </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> a</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">c</span><span style=\\"color:#24292E\\">();</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>函数 b 嵌套在函数 a 内部,函数 a 返回函数 b.这样在执行了 var c = a() 之后,变量 c 变指向了函数 a.再指向 c()就会弹窗显示 i 的值.这段代码就创建了一个\\n闭包.因为函数 a 外的变量 c 引用了函数 a 内的函数 b.就是说,当函数 a 的内部函数 b 被函数 a 外的一个变量引用的时候,就创建了一个闭包.</p>\\n<h2 id=\\"闭包的用途\\" tabindex=\\"-1\\">闭包的用途 <a class=\\"header-anchor\\" href=\\"#闭包的用途\\" aria-label=\\"Permalink to &quot;闭包的用途&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>可以读取函数内部的变量</li>\\n<li>这些变量的值始终保持在内存中</li>\\n<li>模拟私有变量</li>\\n</ul>\\n<p>上面的例子中,i 的值只有 b 函数可以读取.当你不断执行 c()的时候,发现 i 值不断增大,说明 i 没有被内存回收.</p>\\n<h2 id=\\"使用闭包构造模块\\" tabindex=\\"-1\\">使用闭包构造模块 <a class=\\"header-anchor\\" href=\\"#使用闭包构造模块\\" aria-label=\\"Permalink to &quot;使用闭包构造模块&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>模块是一个提供接口却隐藏状态与实现的函数或对象.通过使用函数产生模块,我们几乎可以完全摈弃全局变量的使用.\\n举例来说,假定我们想要给 String 增加一个 deentityify 方法.它的任务是寻找字符串中的 HTML 字符实体并把它们替换为对应的字符.\\n这就需要在一个对象中保存字符实体的名字和它们对应的字符.但我们该在哪里保存这个对象呢?我们可以把它放到一个全局变量中,\\n但全局变量是魔鬼.我们可以把它定义在该函数的内部,但是那会带来运行时的损耗,因为每次执行该函数的时候该字面量都会被求值一次.\\n理想的方式就是使用闭包实现.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">Function</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">prototype</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">method</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">name</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">func</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  this</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">prototype</span><span style=\\"color:#24292E\\">[name] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> func;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">String.</span><span style=\\"color:#6F42C1\\">method</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'deentityify'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  (</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> () {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">    //字符实体表,它映射字符实体打名字到对应的字符.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> entity </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      quot: </span><span style=\\"color:#032F62\\">'\\"'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      lt: </span><span style=\\"color:#032F62\\">'&#x3C;'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      gt: </span><span style=\\"color:#032F62\\">'>'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> () {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">      //查找以'&#x26;'开头和';'结束打子字符串.如果找到就替换.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">replace</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">/&#x26;(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">&#x26;;]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">);/</span><span style=\\"color:#D73A49\\">g</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">a</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">b</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        var</span><span style=\\"color:#24292E\\"> r </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> entity[b];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> r </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'string'</span><span style=\\"color:#D73A49\\"> ?</span><span style=\\"color:#24292E\\"> r </span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#24292E\\"> a;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  })()</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">cosole.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'&#x26;lt;&#x26;quot;&#x26;gt;'</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">deentityify</span><span style=\\"color:#24292E\\">());</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br></div></div><p>通过给 Function.prototype 增加一个 method 方法,我们下次给对象增加方法的时候就不必键入 prototype 这几个字符,省掉了麻烦.\\n请注意最后一行,我们用()运算法立刻调用我们刚刚构造出来的函数.这个调用所创建并返回的函数才是 deentityify 方法.<br>\\n关于这个的用法请参见 wiki:<a href=\\"http://en.wikipedia.org/wiki/Immediately-invoked_function_expression\\" target=\\"_blank\\" rel=\\"noreferrer\\">IIFE</a></p>\\n<h2 id=\\"闭包的缺点\\" tabindex=\\"-1\\">闭包的缺点 <a class=\\"header-anchor\\" href=\\"#闭包的缺点\\" aria-label=\\"Permalink to &quot;闭包的缺点&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>闭包会使局部变量始终存在,内存消耗很大.在 IE 浏览器中它会很容易导致泄露内存.\\n还有就是不要在循环中引用闭包.</p>\\n<h2 id=\\"参考资料\\" tabindex=\\"-1\\">参考资料 <a class=\\"header-anchor\\" href=\\"#参考资料\\" aria-label=\\"Permalink to &quot;参考资料&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>JavaScript 语言精粹</li>\\n<li><a href=\\"https://developer.mozilla.org/zh-CN/docs/JavaScript/Guide/Closures\\" target=\\"_blank\\" rel=\\"noreferrer\\">MDN</a></li>\\n<li><a href=\\"http://baike.baidu.com/view/648413.htm\\" target=\\"_blank\\" rel=\\"noreferrer\\">baike</a></li>\\n</ul>\\n"}]},"relativePath":"page/34/index.md","filePath":"page/[page].md"}`),l={name:"page/34/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const b=s(l,[["render",p]]);export{d as __pageData,b as default};
